239:     /**
240:      * Validates argument counts.
241:      *
242:      * @param argumentCount expected argument count
243:      * @param actualCount actual argument count
244:      * @param throwOnFailure if true, the function throws a {@link ValidationException} if the
245:      *     actual value does not meet the expected argument count
246:      * @return a boolean indicating if expected argument counts match the actual counts
247:      */
248:     public static boolean validateArgumentCount(
249:             ArgumentCount argumentCount, int actualCount, boolean throwOnFailure) {
250:         final int minCount = argumentCount.getMinCount().orElse(0);
251:         if (actualCount < minCount) {
252:             if (throwOnFailure) {
253:                 throw new ValidationException(
254:                         String.format(
255:                                 "Invalid number of arguments. At least %d arguments expected but %d passed.",
256:                                 minCount, actualCount));
257:             }
258:             return false;
259:         }
260:         final int maxCount = argumentCount.getMaxCount().orElse(Integer.MAX_VALUE);
261:         if (actualCount > maxCount) {
262:             if (throwOnFailure) {
263:                 throw new ValidationException(
264:                         String.format(
265:                                 "Invalid number of arguments. At most %d arguments expected but %d passed.",
266:                                 maxCount, actualCount));
267:             }
268:             return false;
269:         }
270:         if (!argumentCount.isValidCount(actualCount)) {
271:             if (throwOnFailure) {
272:                 throw new ValidationException(
273:                         String.format(
274:                                 "Invalid number of arguments. %d arguments passed.", actualCount));
275:             }
276:             return false;
277:         }
278:         return true;
279:     }
