393:     // --------------------------------------------------------------------------------------------
394: 
395:     private static Result runTypeInferenceInternal(
396:             TypeInference typeInference,
397:             CallContext callContext,
398:             @Nullable SurroundingInfo surroundingInfo) {
399:         try {
400:             validateArgumentCount(
401:                     typeInference.getInputTypeStrategy().getArgumentCount(),
402:                     callContext.getArgumentDataTypes().size(),
403:                     true);
404:         } catch (ValidationException e) {
405:             throw createInvalidInputException(typeInference, callContext, e);
406:         }
407: 
408:         final CallContext adaptedCallContext;
409:         try {
410:             // use information of surrounding call to determine output type of this call
411:             final DataType outputType;
412:             if (surroundingInfo != null) {
413:                 outputType =
414:                         surroundingInfo
415:                                 .inferOutputType(callContext.getDataTypeFactory())
416:                                 .orElse(null);
417:             } else {
418:                 outputType = null;
419:             }
420: 
421:             adaptedCallContext = adaptArguments(typeInference, callContext, outputType);
422:         } catch (ValidationException e) {
423:             throw createInvalidInputException(typeInference, callContext, e);
424:         }
425: 
426:         // infer output type first for better error message
427:         // (logically state types should be inferred first)
428:         final DataType outputType =
429:                 inferOutputType(adaptedCallContext, typeInference.getOutputTypeStrategy());
430: 
431:         final LinkedHashMap<String, StateInfo> stateInfos =
432:                 inferStateInfos(adaptedCallContext, typeInference.getStateTypeStrategies());
433: 
434:         return new Result(adaptedCallContext.getArgumentDataTypes(), stateInfos, outputType);
435:     }
