437:     private static String formatStaticArguments(String name, List<StaticArgument> staticArguments) {
438:         final String arguments =
439:                 staticArguments.stream()
440:                         .map(StaticArgument::toString)
441:                         .collect(Collectors.joining(", "));
442:         return String.format("%s(%s)", name, arguments);
443:     }
444: 
445:     private static String formatSignature(String name, Signature s) {
446:         final String arguments =
447:                 s.getArguments().stream()
448:                         .map(TypeInferenceUtil::formatArgument)
449:                         .collect(Collectors.joining(", "));
450:         return String.format("%s(%s)", name, arguments);
451:     }
452: 
453:     private static String formatArgument(Signature.Argument arg) {
454:         final StringBuilder stringBuilder = new StringBuilder();
455:         arg.getName().ifPresent(n -> stringBuilder.append(n).append(" "));
456:         stringBuilder.append(arg.getType());
457:         return stringBuilder.toString();
458:     }
