49:  * <p>The following steps summarize the envisioned type inference process. Not all features are
50:  * implemented or exposed through the API yet (*).
51:  *
52:  * <ul>
53:  *   <li>1. Validate number of arguments.
54:  *   <li>2. (*) Apply assignment operators on the call by permuting operands and adding default
55:  *       values. These are preparations for {@link CallContext}.
56:  *   <li>3. For resolving unknown (NULL) operands: Access the outer wrapping call and try to get its
57:  *       operand type for the return type of the actual call. E.g. for {@code
58:  *       takes_string(this_function(NULL))} infer operands from {@code takes_string(NULL)} and use
59:  *       the inferred string type as the return type of {@code this_function(NULL)}.
60:  *   <li>4. Try infer unknown operands, fail if not possible.
61:  *   <li>5. (*) Check the usage of DEFAULT operands are correct using validator.isOptional().
62:  *   <li>6. Perform input type validation.
63:  *   <li>7. (Optional) Infer accumulator type.
64:  *   <li>8. Infer return type.
65:  *   <li>9. (*) In the planner: Call the strategies again at any point in time to enrich a DataType
66:  *       that has been created from a logical type with a conversion class.
67:  *   <li>10. (*) In the planner: Check for an implementation evaluation method matching the
68:  *       operands. The matching happens class-based. Thus, for example, eval(Object) is valid for
69:  *       (INT). Or eval(Object...) is valid for (INT, STRING). We rely on the conversion classes
70:  *       specified by DataType.
71:  * </ul>
72:  */
73: @Internal
74: public final class TypeInferenceUtil {
75: 
76:     /**
77:      * Runs the entire type inference process.
78:      *
79:      * @param typeInference type inference of the current call
80:      * @param callContext call context of the current call
81:      * @param surroundingInfo information about the outer wrapping call of a current function call
82:      *     for performing input type inference
83:      */
84:     public static Result runTypeInference(
85:             TypeInference typeInference,
86:             CallContext callContext,
87:             @Nullable SurroundingInfo surroundingInfo) {
88:         try {
89:             return runTypeInferenceInternal(typeInference, callContext, surroundingInfo);
90:         } catch (ValidationException e) {
91:             throw createInvalidCallException(callContext, e);
92:         } catch (Throwable t) {
93:             throw createUnexpectedException(callContext, t);
94:         }
95:     }
96: 
97:     /**
98:      * Adapts the call's argument if necessary.
99:      *
100:      * <p>This includes casts that need to be inserted, reordering of arguments (*), or insertion of
101:      * default values (*) where (*) is future work.
102:      */
103:     public static CallContext castArguments(
104:             TypeInference typeInference, CallContext callContext, @Nullable DataType outputType) {
105:         return castArguments(typeInference, callContext, outputType, true);
106:     }
107: 
108:     private static CallContext castArguments(
109:             TypeInference typeInference,
110:             CallContext callContext,
111:             @Nullable DataType outputType,
112:             boolean throwOnInferInputFailure) {
113:         final List<DataType> actualTypes = callContext.getArgumentDataTypes();
114: 
115:         typeInference
116:                 .getStaticArguments()
117:                 .ifPresent(
118:                         staticArgs -> {
119:                             if (actualTypes.size() != staticArgs.size()) {
120:                                 throw new ValidationException(
121:                                         String.format(
122:                                                 "Invalid number of arguments. %d arguments expected after argument expansion but %d passed.",
123:                                                 staticArgs.size(), actualTypes.size()));
124:                             }
125:                         });
126: 
127:         final AdaptedCallContext adaptedCallContext =
128:                 inferInputTypes(typeInference, callContext, outputType, throwOnInferInputFailure);
129: 
130:         // final check if the call is valid after casting
131:         final List<DataType> expectedTypes = adaptedCallContext.getArgumentDataTypes();
132:         for (int pos = 0; pos < actualTypes.size(); pos++) {
133:             final DataType expectedType = expectedTypes.get(pos);
134:             final DataType actualType = actualTypes.get(pos);
135:             if (!supportsImplicitCast(actualType.getLogicalType(), expectedType.getLogicalType())) {
136:                 if (!throwOnInferInputFailure) {
137:                     // abort the adaption, e.g. if a NULL is passed for a NOT NULL argument
138:                     return callContext;
139:                 }
140:                 throw new ValidationException(
141:                         String.format(
142:                                 "Invalid argument type at position %d. Data type %s expected but %s passed.",
143:                                 pos, expectedType, actualType));
144:             }
145:         }
146: 
147:         return adaptedCallContext;
148:     }
149: 
150:     /**
151:      * Infers an output type using the given {@link TypeStrategy}. It assumes that input arguments
152:      * have been adapted before if necessary.
153:      */
154:     public static DataType inferOutputType(
155:             CallContext callContext, TypeStrategy outputTypeStrategy) {
156:         final Optional<DataType> potentialOutputType = outputTypeStrategy.inferType(callContext);
157:         if (potentialOutputType.isEmpty()) {
158:             throw new ValidationException(
159:                     "Could not infer an output type for the given arguments.");
160:         }
161:         final DataType outputType = potentialOutputType.get();
162: 
163:         if (isUnknown(outputType)) {
164:             throw new ValidationException(
165:                     "Could not infer an output type for the given arguments. Untyped NULL received.");
166:         }
167:         return outputType;
168:     }
169: 
170:     /**
171:      * Infers {@link StateInfo}s using the given {@link StateTypeStrategy}s. It assumes that input
172:      * arguments have been adapted before if necessary.
173:      */
174:     public static LinkedHashMap<String, StateInfo> inferStateInfos(
175:             CallContext callContext, LinkedHashMap<String, StateTypeStrategy> stateTypeStrategies) {
176:         return stateTypeStrategies.entrySet().stream()
177:                 .map(
178:                         e ->
179:                                 Map.entry(
180:                                         e.getKey(),
181:                                         inferStateInfo(callContext, e.getKey(), e.getValue())))
182:                 .collect(
183:                         Collectors.toMap(
184:                                 Map.Entry::getKey,
185:                                 Map.Entry::getValue,
186:                                 (x, y) -> y,
187:                                 LinkedHashMap::new));
188:     }
189: 
190:     /** Generates a signature of the given {@link FunctionDefinition}. */
191:     public static String generateSignature(
192:             TypeInference typeInference, String name, FunctionDefinition definition) {
193:         final List<StaticArgument> staticArguments =
194:                 typeInference.getStaticArguments().orElse(null);
195:         if (staticArguments != null) {
196:             return formatStaticArguments(name, staticArguments);
197:         }
198:         return typeInference.getInputTypeStrategy().getExpectedSignatures(definition).stream()
199:                 .map(s -> formatSignature(name, s))
200:                 .collect(Collectors.joining("\n"));
201:     }
202: 
203:     /** Returns an exception for invalid input arguments. */
204:     public static ValidationException createInvalidInputException(
205:             TypeInference typeInference, CallContext callContext, ValidationException cause) {
206:         return new ValidationException(
207:                 String.format(
208:                         "Invalid input arguments. Expected signatures are:\n%s",
209:                         generateSignature(
210:                                 typeInference,
211:                                 callContext.getName(),
212:                                 callContext.getFunctionDefinition())),
213:                 cause);
214:     }
215: 
216:     /** Returns an exception for an invalid call to a function. */
217:     public static ValidationException createInvalidCallException(
218:             CallContext callContext, ValidationException cause) {
219:         return new ValidationException(
220:                 String.format(
221:                         "Invalid function call:\n%s(%s)",
222:                         callContext.getName(),
223:                         callContext.getArgumentDataTypes().stream()
224:                                 .map(DataType::toString)
225:                                 .collect(Collectors.joining(", "))),
226:                 cause);
227:     }
228: 
229:     /** Returns an exception for an unexpected error during type inference. */
230:     public static TableException createUnexpectedException(
231:             CallContext callContext, Throwable cause) {
232:         return new TableException(
233:                 String.format(
234:                         "Unexpected error in type inference logic of function '%s'. This is a bug.",
235:                         callContext.getName()),
236:                 cause);
237:     }
238: 
239:     /**
240:      * Validates argument counts.
241:      *
242:      * @param argumentCount expected argument count
243:      * @param actualCount actual argument count
244:      * @param throwOnFailure if true, the function throws a {@link ValidationException} if the
245:      *     actual value does not meet the expected argument count
246:      * @return a boolean indicating if expected argument counts match the actual counts
247:      */
248:     public static boolean validateArgumentCount(
249:             ArgumentCount argumentCount, int actualCount, boolean throwOnFailure) {
250:         final int minCount = argumentCount.getMinCount().orElse(0);
251:         if (actualCount < minCount) {
252:             if (throwOnFailure) {
253:                 throw new ValidationException(
254:                         String.format(
255:                                 "Invalid number of arguments. At least %d arguments expected but %d passed.",
256:                                 minCount, actualCount));
257:             }
258:             return false;
259:         }
260:         final int maxCount = argumentCount.getMaxCount().orElse(Integer.MAX_VALUE);
261:         if (actualCount > maxCount) {
262:             if (throwOnFailure) {
263:                 throw new ValidationException(
264:                         String.format(
265:                                 "Invalid number of arguments. At most %d arguments expected but %d passed.",
266:                                 maxCount, actualCount));
267:             }
268:             return false;
269:         }
270:         if (!argumentCount.isValidCount(actualCount)) {
271:             if (throwOnFailure) {
272:                 throw new ValidationException(
273:                         String.format(
274:                                 "Invalid number of arguments. %d arguments passed.", actualCount));
275:             }
276:             return false;
277:         }
278:         return true;
279:     }
280: 
281:     /**
282:      * Information what the outer world (i.e. an outer wrapping call) expects from the current
283:      * function call. This can be helpful for an {@link InputTypeStrategy}.
284:      *
285:      * @see CallContext#getOutputDataType()
286:      */
287:     @Internal
288:     public interface SurroundingInfo {
289: 
290:         static SurroundingInfo of(
291:                 String name,
292:                 FunctionDefinition functionDefinition,
293:                 TypeInference typeInference,
294:                 int argumentCount,
295:                 int innerCallPosition,
296:                 boolean isGroupedAggregation) {
297:             return typeFactory -> {
298:                 final boolean isValidCount =
299:                         validateArgumentCount(
300:                                 typeInference.getInputTypeStrategy().getArgumentCount(),
301:                                 argumentCount,
302:                                 false);
303:                 if (!isValidCount) {
304:                     return Optional.empty();
305:                 }
306:                 // for "takes_string(this_function(NULL))" simulate "takes_string(NULL)"
307:                 // for retrieving the output type of "this_function(NULL)"
308:                 final CallContext callContext =
309:                         new UnknownCallContext(
310:                                 typeFactory,
311:                                 name,
312:                                 functionDefinition,
313:                                 argumentCount,
314:                                 isGroupedAggregation);
315: 
316:                 // We might not be able to infer the input types at this moment, if the surrounding
317:                 // function does not provide an explicit input type strategy.
318:                 final CallContext adaptedContext =
319:                         castArguments(typeInference, callContext, null, false);
320:                 return typeInference
321:                         .getInputTypeStrategy()
322:                         .inferInputTypes(adaptedContext, false)
323:                         .map(dataTypes -> dataTypes.get(innerCallPosition));
324:             };
325:         }
326: 
327:         static SurroundingInfo of(DataType dataType) {
328:             return typeFactory -> Optional.of(dataType);
329:         }
330: 
331:         Optional<DataType> inferOutputType(DataTypeFactory typeFactory);
332:     }
333: 
334:     /**
335:      * The result of a type inference run. It contains information about how arguments need to be
336:      * adapted in order to comply with the function's signature.
337:      *
338:      * <p>This includes casts that need to be inserted, reordering of arguments (*), or insertion of
339:      * default values (*) where (*) is future work.
340:      */
341:     @Internal
342:     public static final class Result {
343: 
344:         private final List<DataType> expectedArgumentTypes;
345: 
346:         private final LinkedHashMap<String, StateInfo> stateInfos;
347: 
348:         private final DataType outputDataType;
349: 
350:         public Result(
351:                 List<DataType> expectedArgumentTypes,
352:                 LinkedHashMap<String, StateInfo> stateInfos,
353:                 DataType outputDataType) {
354:             this.expectedArgumentTypes = expectedArgumentTypes;
355:             this.stateInfos = stateInfos;
356:             this.outputDataType = outputDataType;
357:         }
358: 
359:         public List<DataType> getExpectedArgumentTypes() {
360:             return expectedArgumentTypes;
361:         }
362: 
363:         public LinkedHashMap<String, StateInfo> getStateInfos() {
364:             return stateInfos;
365:         }
366: 
367:         public DataType getOutputDataType() {
368:             return outputDataType;
369:         }
370:     }
371: 
372:     /** Result of running {@link StateTypeStrategy}. */
373:     @Internal
374:     public static final class StateInfo {
375: 
376:         private final DataType dataType;
377:         private final @Nullable Duration timeToLive;
378: 
379:         private StateInfo(DataType dataType, @Nullable Duration timeToLive) {
380:             this.dataType = dataType;
381:             this.timeToLive = timeToLive;
382:         }
383: 
384:         public DataType getDataType() {
385:             return dataType;
386:         }
387: 
388:         public Optional<Duration> getTimeToLive() {
389:             return Optional.ofNullable(timeToLive);
390:         }
391:     }
392: 
393:     // --------------------------------------------------------------------------------------------
394: 
395:     private static Result runTypeInferenceInternal(
396:             TypeInference typeInference,
397:             CallContext callContext,
398:             @Nullable SurroundingInfo surroundingInfo) {
399:         try {
400:             validateArgumentCount(
401:                     typeInference.getInputTypeStrategy().getArgumentCount(),
402:                     callContext.getArgumentDataTypes().size(),
403:                     true);
404:         } catch (ValidationException e) {
405:             throw createInvalidInputException(typeInference, callContext, e);
406:         }
407: 
408:         final CallContext adaptedCallContext;
409:         try {
410:             // use information of surrounding call to determine output type of this call
411:             final DataType outputType;
412:             if (surroundingInfo != null) {
413:                 outputType =
414:                         surroundingInfo
415:                                 .inferOutputType(callContext.getDataTypeFactory())
416:                                 .orElse(null);
417:             } else {
418:                 outputType = null;
419:             }
420: 
421:             adaptedCallContext = castArguments(typeInference, callContext, outputType);
422:         } catch (ValidationException e) {
423:             throw createInvalidInputException(typeInference, callContext, e);
424:         }
425: 
426:         // infer output type first for better error message
427:         // (logically state types should be inferred first)
428:         final DataType outputType =
429:                 inferOutputType(adaptedCallContext, typeInference.getOutputTypeStrategy());
430: 
431:         final LinkedHashMap<String, StateInfo> stateInfos =
432:                 inferStateInfos(adaptedCallContext, typeInference.getStateTypeStrategies());
433: 
434:         return new Result(adaptedCallContext.getArgumentDataTypes(), stateInfos, outputType);
435:     }
