101: 
102:         ResolvingCallVisitor(ResolutionContext context, @Nullable SurroundingInfo surroundingInfo) {
103:             super(context);
104:             this.surroundingInfo = surroundingInfo;
105:         }
106: 
107:         @Override
108:         public List<ResolvedExpression> visit(UnresolvedCallExpression unresolvedCall) {
109:             final FunctionDefinition definition;
110:             // clean functions that were not registered in a catalog
111:             if (!unresolvedCall.getFunctionIdentifier().isPresent()) {
112:                 definition =
113:                         prepareInlineUserDefinedFunction(unresolvedCall.getFunctionDefinition());
114:             } else {
115:                 definition = unresolvedCall.getFunctionDefinition();
116:             }
117: 
118:             final String name =
119:                     unresolvedCall
120:                             .getFunctionIdentifier()
121:                             .map(FunctionIdentifier::toString)
122:                             .orElseGet(definition::toString);
123: 
124:             final Optional<TypeInference> typeInference = getOptionalTypeInference(definition);
125: 
126:             // resolve the children with information from the current call
127:             final List<ResolvedExpression> resolvedArgs = new ArrayList<>();
128:             final int argCount = unresolvedCall.getChildren().size();
129: 
130:             for (int i = 0; i < argCount; i++) {
131:                 final int currentPos = i;
132:                 final SurroundingInfo surroundingInfo =
133:                         typeInference
134:                                 .map(
135:                                         inference ->
136:                                                 SurroundingInfo.of(
137:                                                         name,
138:                                                         definition,
139:                                                         inference,
140:                                                         argCount,
141:                                                         currentPos,
142:                                                         resolutionContext.isGroupedAggregation()))
143:                                 .orElse(null);
144:                 final ResolvingCallVisitor childResolver =
145:                         new ResolvingCallVisitor(resolutionContext, surroundingInfo);
146:                 resolvedArgs.addAll(unresolvedCall.getChildren().get(i).accept(childResolver));
147:             }
148: 
149:             if (definition == BuiltInFunctionDefinitions.FLATTEN) {
150:                 return executeFlatten(resolvedArgs);
151:             }
152: 
153:             return Collections.singletonList(
154:                     typeInference
155:                             .map(
156:                                     newInference ->
157:                                             runTypeInference(
158:                                                     name,
159:                                                     unresolvedCall,
160:                                                     newInference,
161:                                                     resolvedArgs,
162:                                                     surroundingInfo))
163:                             .orElseThrow(
164:                                     () ->
165:                                             new TableException(
166:                                                     "Could not get a type inference for function: "
167:                                                             + name)));
168:         }
