275:     /**
276:      * Sets the parallelism for operations executed through this environment. Setting a parallelism
277:      * of x here will cause all operators (such as join, map, reduce) to run with x parallel
278:      * instances.
279:      *
280:      * <p>This method overrides the default parallelism for this environment. The local execution
281:      * environment uses by default a value equal to the number of hardware contexts (CPU cores /
282:      * threads). When executing the program via the command line client from a JAR file, the default
283:      * parallelism is the one configured for that setup.
284:      *
285:      * @param parallelism The parallelism to use
286:      */
287:     public ExecutionConfig setParallelism(int parallelism) {
288:         if (parallelism != PARALLELISM_UNKNOWN) {
289:             if (parallelism < 1 && parallelism != PARALLELISM_DEFAULT) {
290:                 throw new IllegalArgumentException(
291:                         "Parallelism must be at least one, or ExecutionConfig.PARALLELISM_DEFAULT (use system default).");
292:             }
293:             configuration.set(CoreOptions.DEFAULT_PARALLELISM, parallelism);
294:         }
295:         return this;
296:     }
