585:     /** Configuration settings for the closure cleaner. */
586:     public enum ClosureCleanerLevel implements DescribedEnum {
587:         NONE(text("Disables the closure cleaner completely.")),
588: 
589:         TOP_LEVEL(text("Cleans only the top-level class without recursing into fields.")),
590: 
591:         RECURSIVE(text("Cleans all fields recursively."));
592: 
593:         private final InlineElement description;
594: 
595:         ClosureCleanerLevel(InlineElement description) {
596:             this.description = description;
597:         }
