1086: 
1087:     @VisibleForTesting
1088:     static boolean hasDesiredResources(
1089:             ResourceCounter desiredResources, Collection<? extends SlotInfo> freeSlots) {
1090:         ResourceCounter outstandingResources = desiredResources;
1091:         final Iterator<? extends SlotInfo> slotIterator = freeSlots.iterator();
1092: 
1093:         while (!outstandingResources.isEmpty() && slotIterator.hasNext()) {
1094:             final SlotInfo slotInfo = slotIterator.next();
1095:             final ResourceProfile resourceProfile = slotInfo.getResourceProfile();
1096: 
1097:             if (outstandingResources.containsResource(resourceProfile)) {
1098:                 outstandingResources = outstandingResources.subtract(resourceProfile, 1);
1099:             } else {
1100:                 outstandingResources = outstandingResources.subtract(ResourceProfile.UNKNOWN, 1);
1101:             }
1102:         }
1103: 
1104:         return outstandingResources.isEmpty();
1105:     }
