1404: 
1405:         backgroundTask =
1406:                 backgroundTask.runAfter(
1407:                         () -> createExecutionGraphAndRestoreState(adjustedParallelismStore),
1408:                         ioExecutor);
1409: 
1410:         return FutureUtils.switchExecutor(
1411:                 backgroundTask.getResultFuture(), getMainThreadExecutor());
1412:     }
