1472:     private FailureResult howToHandleFailure(Throwable failure) {
1473:         if (ExecutionFailureHandler.isUnrecoverableError(failure)) {
1474:             return FailureResult.canNotRestart(
1475:                     new JobException("The failure is not recoverable", failure));
1476:         }
1477: 
1478:         restartBackoffTimeStrategy.notifyFailure(failure);
1479:         if (restartBackoffTimeStrategy.canRestart()) {
1480:             return FailureResult.canRestart(
1481:                     failure, Duration.ofMillis(restartBackoffTimeStrategy.getBackoffTime()));
1482:         } else {
1483:             return FailureResult.canNotRestart(
1484:                     new JobException(
