531:         declarativeSlotPool.registerNewSlotsListener(this::newResourcesAvailable);
532: 
533:         this.componentMainThreadExecutor = mainThreadExecutor;
534: 
535:         this.executionGraphFactory = executionGraphFactory;
536: 
537:         final JobStatusStore jobStatusStore = new JobStatusStore(initializationTimestamp);
538:         final Collection<JobStatusListener> tmpJobStatusListeners = new ArrayList<>();
539:         tmpJobStatusListeners.add(Preconditions.checkNotNull(jobStatusListener));
540:         tmpJobStatusListeners.add(jobStatusStore);
541: 
542:         final MetricOptions.JobStatusMetricsSettings jobStatusMetricsSettings =
