403:     private MemorySegment requestMemorySegmentBlocking(int targetChannel)
404:             throws InterruptedException {
405:         MemorySegment segment;
406:         while ((segment = requestMemorySegment(targetChannel)) == null) {
407:             try {
408:                 // wait until available
409:                 getAvailableFuture().get();
410:             } catch (ExecutionException e) {
411:                 LOG.error("The available future is completed exceptionally.", e);
412:                 ExceptionUtils.rethrow(e);
413:             }
414:         }
415:         return segment;
416:     }
