307:     private void internalRecycleMemorySegments(Collection<MemorySegment> segments) {
308:         CompletableFuture<?> toNotify = null;
309:         synchronized (availableMemorySegments) {
310:             if (availableMemorySegments.isEmpty() && !segments.isEmpty()) {
311:                 toNotify = availabilityHelper.getUnavailableToResetAvailable();
312:             }
313:             availableMemorySegments.addAll(segments);
314:             availableMemorySegments.notifyAll();
315:         }
316: 
317:         if (toNotify != null) {
318:             toNotify.complete(null);
319:         }
320:     }
