113:                 "The timeout for requesting exclusive buffers should be positive.");
114:         this.requestSegmentsTimeout = requestSegmentsTimeout;
115: 
116:         final long sizeInLong = (long) segmentSize;
117: 
118:         try {
119:             this.availableMemorySegments = new ArrayDeque<>(numberOfSegmentsToAllocate);
120:         } catch (OutOfMemoryError err) {
121:             throw new OutOfMemoryError(
122:                     "Could not allocate buffer queue of length "
123:                             + numberOfSegmentsToAllocate
124:                             + " - "
125:                             + err.getMessage());
126:         }
127: 
128:         try {
129:             for (int i = 0; i < numberOfSegmentsToAllocate; i++) {
130:                 availableMemorySegments.add(
131:                         MemorySegmentFactory.allocateUnpooledOffHeapMemory(segmentSize, null));
132:             }
133:         } catch (OutOfMemoryError err) {
134:             int allocated = availableMemorySegments.size();
135: 
136:             // free some memory
137:             availableMemorySegments.clear();
138: 
139:             long requiredMb = (sizeInLong * numberOfSegmentsToAllocate) >> 20;
140:             long allocatedMb = (sizeInLong * allocated) >> 20;
141:             long missingMb = requiredMb - allocatedMb;
