143:             throw new OutOfMemoryError(
144:                     "Could not allocate enough memory segments for NetworkBufferPool "
145:                             + "(required (MB): "
146:                             + requiredMb
147:                             + ", allocated (MB): "
148:                             + allocatedMb
149:                             + ", missing (MB): "
150:                             + missingMb
151:                             + "). Cause: "
152:                             + err.getMessage());
153:         }
