196:     /**
197:      * Unpooled memory segments are requested directly from {@link NetworkBufferPool}, as opposed to
198:      * pooled segments, that are requested through {@link BufferPool} that was created from this
199:      * {@link NetworkBufferPool} (see {@link #createBufferPool}). They are used for example for
200:      * exclusive {@link RemoteInputChannel} credits, that are permanently assigned to that channel,
201:      * and never returned to any {@link BufferPool}. As opposed to pooled segments, when requested,
202:      * unpooled segments needs to be accounted against {@link #numTotalRequiredBuffers}, which might
203:      * require redistribution of the segments.
204:      */
205:     @Override
206:     public List<MemorySegment> requestUnpooledMemorySegments(int numberOfSegmentsToRequest)
207:             throws IOException {
208:         checkArgument(
209:                 numberOfSegmentsToRequest >= 0,
210:                 "Number of buffers to request must be non-negative.");
211: 
212:         synchronized (factoryLock) {
213:             if (isDestroyed) {
214:                 throw new IllegalStateException("Network buffer pool has already been destroyed.");
215:             }
216: 
217:             if (numberOfSegmentsToRequest == 0) {
218:                 return Collections.emptyList();
219:             }
220: 
221:             tryRedistributeBuffers(numberOfSegmentsToRequest);
222:         }
223: 
224:         try {
225:             return internalRequestMemorySegments(numberOfSegmentsToRequest);
226:         } catch (IOException exception) {
227:             revertRequiredBuffers(numberOfSegmentsToRequest);
228:             ExceptionUtils.rethrowIOException(exception);
229:             return null;
230:         }
231:     }
