233:     private List<MemorySegment> internalRequestMemorySegments(int numberOfSegmentsToRequest)
234:             throws IOException {
235:         final List<MemorySegment> segments = new ArrayList<>(numberOfSegmentsToRequest);
236:         try {
237:             final Deadline deadline = Deadline.fromNow(requestSegmentsTimeout);
238:             while (true) {
239:                 if (isDestroyed) {
240:                     throw new IllegalStateException("Buffer pool is destroyed.");
241:                 }
242: 
243:                 MemorySegment segment;
244:                 synchronized (availableMemorySegments) {
245:                     if ((segment = internalRequestMemorySegment()) == null) {
246:                         availableMemorySegments.wait(2000);
247:                     }
248:                 }
249:                 if (segment != null) {
250:                     segments.add(segment);
251:                 }
252: 
253:                 if (segments.size() >= numberOfSegmentsToRequest) {
254:                     break;
255:                 }
256: 
257:                 if (!deadline.hasTimeLeft()) {
258:                     throw new IOException(
259:                             String.format(
260:                                     "Timeout triggered when requesting exclusive buffers: %s, "
261:                                             + " or you may increase the timeout which is %dms by setting the key '%s'.",
262:                                     getConfigDescription(),
263:                                     requestSegmentsTimeout.toMillis(),
264:                                     NettyShuffleEnvironmentOptions.NETWORK_BUFFERS_REQUEST_TIMEOUT
265:                                             .key()));
266:                 }
267:             }
268:         } catch (Throwable e) {
269:             internalRecycleMemorySegments(segments);
270:             ExceptionUtils.rethrowIOException(e);
271:         }
272: 
273:         return segments;
274:     }
