472:     private static class TimeBasedBufferingSinkWriter
473:             extends TestSinkV2.DefaultCommittingSinkWriter<Integer>
474:             implements ProcessingTimeService.ProcessingTimeCallback {
475: 
476:         private final List<String> cachedCommittables = new ArrayList<>();
477:         private ProcessingTimeService processingTimeService;
478: 
479:         @Override
480:         public void write(Integer element, Context context) {
481:             cachedCommittables.add(
482:                     Tuple3.of(element, context.timestamp(), context.currentWatermark()).toString());
483:         }
484: 
485:         @Override
486:         public void onProcessingTime(long time) {
487:             elements.addAll(cachedCommittables);
488:             cachedCommittables.clear();
489:             this.processingTimeService.registerTimer(time + 1000, this);
490:         }
491: 
492:         @Override
493:         public void init(WriterInitContext context) {
494:             this.processingTimeService = context.getProcessingTimeService();
495:             this.processingTimeService.registerTimer(1000, this);
496:         }
497:     }
