465:     @Override
466:     public void enableCheckpointing(
467:             CheckpointCoordinatorConfiguration chkConfig,
468:             List<MasterTriggerRestoreHook<?>> masterHooks,
469:             CheckpointIDCounter checkpointIDCounter,
470:             CompletedCheckpointStore checkpointStore,
471:             StateBackend checkpointStateBackend,
472:             CheckpointStorage checkpointStorage,
473:             CheckpointStatsTracker statsTracker,
474:             CheckpointsCleaner checkpointsCleaner,
475:             String changelogStorageName) {
476: 
477:         checkState(state == JobStatus.CREATED, "Job must be in CREATED state");
478:         checkState(checkpointCoordinator == null, "checkpointing already enabled");
479: 
480:         final Collection<OperatorCoordinatorCheckpointContext> operatorCoordinators =
481:                 buildOpCoordinatorCheckpointContexts();
482: 
483:         checkpointStatsTracker = checkNotNull(statsTracker, "CheckpointStatsTracker");
484:         checkpointCoordinatorConfiguration =
485:                 checkNotNull(chkConfig, "CheckpointCoordinatorConfiguration");
486: 
487:         CheckpointFailureManager failureManager =
488:                 new CheckpointFailureManager(
489:                         chkConfig.getTolerableCheckpointFailureNumber(),
490:                         new CheckpointFailureManager.FailJobCallback() {
491:                             @Override
492:                             public void failJob(Throwable cause) {
493:                                 getJobMasterMainThreadExecutor().execute(() -> failGlobal(cause));
494:                             }
495: 
496:                             @Override
497:                             public void failJobDueToTaskFailure(
498:                                     Throwable cause, ExecutionAttemptID failingTask) {
499:                                 getJobMasterMainThreadExecutor()
500:                                         .execute(
501:                                                 () ->
502:                                                         failGlobalIfExecutionIsStillRunning(
503:                                                                 cause, failingTask));
504:                             }
505:                         });
506: 
507:         checkState(checkpointCoordinatorTimer == null);
508: 
509:         checkpointCoordinatorTimer =
510:                 MdcUtils.scopeToJob(
511:                         getJobID(),
512:                         Executors.newSingleThreadScheduledExecutor(
513:                                 new DispatcherThreadFactory(
514:                                         Thread.currentThread().getThreadGroup(),
515:                                         "Checkpoint Timer")));
516: 
517:         // create the coordinator that triggers and commits checkpoints and holds the state
518:         checkpointCoordinator =
519:                 new CheckpointCoordinator(
520:                         jobInformation.getJobId(),
521:                         chkConfig,
522:                         operatorCoordinators,
523:                         checkpointIDCounter,
524:                         checkpointStore,
525:                         checkpointStorage,
526:                         ioExecutor,
527:                         checkpointsCleaner,
528:                         new ScheduledExecutorServiceAdapter(checkpointCoordinatorTimer),
529:                         failureManager,
530:                         createCheckpointPlanCalculator(
531:                                 chkConfig.isEnableCheckpointsAfterTasksFinish()),
532:                         checkpointStatsTracker);
533: 
534:         // register the master hooks on the checkpoint coordinator
535:         for (MasterTriggerRestoreHook<?> hook : masterHooks) {
536:             if (!checkpointCoordinator.addMasterHook(hook)) {
537:                 LOG.warn(
538:                         "Trying to register multiple checkpoint hooks with the name: {}",
539:                         hook.getIdentifier());
540:             }
541:         }
542: 
543:         if (checkpointCoordinator.isPeriodicCheckpointingConfigured()) {
544:             // the periodic checkpoint scheduler is activated and deactivated as a result of
545:             // job status and topology changes (running & all edges non-blocking -> on, all
546:             // other states -> off)
547:             boolean allTasksOutputNonBlocking =
548:                     tasks.values().stream()
549:                             .noneMatch(vertex -> vertex.getJobVertex().isAnyOutputBlocking());
550:             registerJobStatusListener(
551:                     checkpointCoordinator.createActivatorDeactivator(allTasksOutputNonBlocking));
552:         }
553: 
554:         this.stateBackendName = checkpointStateBackend.getName();
555:         this.stateChangelogEnabled =
556:                 TernaryBoolean.fromBoolean(
557:                         StateBackendLoader.isChangelogStateBackend(checkpointStateBackend));
558: 
559:         this.checkpointStorageName = checkpointStorage.getClass().getSimpleName();
560:         this.changelogStorageName = changelogStorageName;
561:     }
