1494:     private void maybeReleasePartitionGroupsFor(final Execution attempt) {
1495:         final ExecutionVertexID finishedExecutionVertex = attempt.getVertex().getID();
1496: 
1497:         if (attempt.getState() == ExecutionState.FINISHED) {
1498:             final List<ConsumedPartitionGroup> releasablePartitionGroups =
1499:                     partitionGroupReleaseStrategy.vertexFinished(finishedExecutionVertex);
1500:             releasePartitionGroups(releasablePartitionGroups);
1501:         } else {
1502:             partitionGroupReleaseStrategy.vertexUnfinished(finishedExecutionVertex);
1503:         }
1504:     }
1505: 
1506:     private void releasePartitionGroups(
1507:             final List<ConsumedPartitionGroup> releasablePartitionGroups) {
1508: 
1509:         if (releasablePartitionGroups.size() > 0) {
1510:             final List<ResultPartitionID> releasablePartitionIds = new ArrayList<>();
1511: 
1512:             // Remove the cache of ShuffleDescriptors when ConsumedPartitionGroups are released
1513:             for (ConsumedPartitionGroup releasablePartitionGroup : releasablePartitionGroups) {
1514:                 IntermediateResult totalResult =
1515:                         checkNotNull(
1516:                                 intermediateResults.get(
1517:                                         releasablePartitionGroup.getIntermediateDataSetID()));
1518:                 for (IntermediateResultPartitionID partitionId : releasablePartitionGroup) {
1519:                     IntermediateResultPartition partition =
1520:                             totalResult.getPartitionById(partitionId);
1521:                     partition.markPartitionGroupReleasable(releasablePartitionGroup);
1522:                     if (partition.canBeReleased()) {
1523:                         releasablePartitionIds.add(createResultPartitionId(partitionId));
1524:                     }
1525:                 }
1526:                 totalResult.clearCachedInformationForPartitionGroup(releasablePartitionGroup);
1527:             }
1528: 
1529:             partitionTracker.stopTrackingAndReleasePartitions(releasablePartitionIds);
1530:         }
1531:     }
