1535:             final IntermediateResultPartitionID resultPartitionId) {
1536:         final SchedulingResultPartition schedulingResultPartition =
1537:                 getSchedulingTopology().getResultPartition(resultPartitionId);
1538:         final SchedulingExecutionVertex producer = schedulingResultPartition.getProducer();
1539:         final ExecutionVertexID producerId = producer.getId();
1540:         final JobVertexID jobVertexId = producerId.getJobVertexId();
1541:         final ExecutionJobVertex jobVertex = getJobVertex(jobVertexId);
1542:         checkNotNull(jobVertex, "Unknown job vertex %s", jobVertexId);
