958:     @Override
959:     public void initializeJobVertex(
960:             ExecutionJobVertex ejv,
961:             long createTimestamp,
962:             Map<IntermediateDataSetID, JobVertexInputInfo> jobVertexInputInfos)
963:             throws JobException {
964: 
965:         checkNotNull(ejv);
966:         checkNotNull(jobVertexInputInfos);
967: 
968:         jobVertexInputInfos.forEach(
969:                 (resultId, info) ->
970:                         this.vertexInputInfoStore.put(ejv.getJobVertexId(), resultId, info));
971: 
972:         ejv.initialize(
973:                 executionHistorySizeLimit,
974:                 rpcTimeout,
975:                 createTimestamp,
976:                 this.initialAttemptCounts.getAttemptCounts(ejv.getJobVertexId()),
977:                 executionPlanSchedulingContext);
978: 
979:         ejv.connectToPredecessors(this.intermediateResults);
980: 
981:         for (IntermediateResult res : ejv.getProducedDataSets()) {
982:             IntermediateResult previousDataSet =
983:                     this.intermediateResults.putIfAbsent(res.getId(), res);
984:             if (previousDataSet != null) {
985:                 throw new JobException(
986:                         String.format(
987:                                 "Encountered two intermediate data set with ID %s : previous=[%s] / new=[%s]",
988:                                 res.getId(), res, previousDataSet));
989:             }
990:         }
991: 
992:         registerExecutionVerticesAndResultPartitionsFor(ejv);
993: 
994:         // enrich network memory.
995:         SlotSharingGroup slotSharingGroup = ejv.getSlotSharingGroup();
996:         if (areJobVerticesAllInitialized(slotSharingGroup)) {
997:             SsgNetworkMemoryCalculationUtils.enrichNetworkMemory(
998:                     slotSharingGroup, this::getJobVertex, shuffleMaster);
999:         }
1000:     }
1001: 
1002:     private boolean areJobVerticesAllInitialized(final SlotSharingGroup group) {
1003:         for (JobVertexID jobVertexId : group.getJobVertexIds()) {
1004:             final ExecutionJobVertex jobVertex = getJobVertex(jobVertexId);
1005:             checkNotNull(jobVertex, "Unknown job vertex %s", jobVertexId);
1006:             if (!jobVertex.isInitialized()) {
1007:                 return false;
1008:             }
1009:         }
1010:         return true;
1011:     }
