1069:     private CompletableFuture<Void> resetExecutionGraph(
1070:             Function<ExecutionJobVertex, CompletableFuture<Void>> perVertexOperationAsync) {
1071:         assertRunningInJobMasterMainThread();
1072: 
1073:         incrementRestarts();
1074: 
1075:         // cancel ongoing scheduling action
1076:         if (schedulingFuture != null) {
1077:             schedulingFuture.cancel(false);
1078:         }
1079: 
1080:         return applyToVertexAsync(perVertexOperationAsync);
1081:     }
