1091:     @Override
1092:     public void suspend(Throwable suspensionCause) {
1093: 
1094:         assertRunningInJobMasterMainThread();
1095: 
1096:         if (state.isTerminalState()) {
1097:             // stay in a terminal state
1098:             return;
1099:         } else if (transitionState(state, JobStatus.SUSPENDED, suspensionCause)) {
1100:             initFailureCause(suspensionCause, System.currentTimeMillis());
1101: 
1102:             final CompletableFuture<Void> jobVerticesTerminationFuture =
1103:                     resetExecutionGraph(ExecutionJobVertex::suspend);
1104: 
1105:             checkState(jobVerticesTerminationFuture.isDone(), "Suspend needs to happen atomically");
1106: 
1107:             jobVerticesTerminationFuture.whenComplete(
1108:                     (Void ignored, Throwable throwable) -> {
1109:                         if (throwable != null) {
1110:                             LOG.debug("Could not properly suspend the execution graph.", throwable);
1111:                         }
1112: 
1113:                         onTerminalState(state);
1114:                         LOG.info("Job {} has been suspended.", getJobID());
1115:                     });
1116:         } else {
1117:             throw new IllegalStateException(
1118:                     String.format(
1119:                             "Could not suspend because transition from %s to %s failed.",
1120:                             state, JobStatus.SUSPENDED));
1121:         }
1122:     }
