1264:     private void jobFinished() {
1265:         assertRunningInJobMasterMainThread();
1266: 
1267:         // check whether we are still in "RUNNING" and trigger the final cleanup
1268:         if (state == JobStatus.RUNNING) {
1269:             // we do the final cleanup in the I/O executor, because it may involve
1270:             // some heavier work
1271: 
1272:             try {
1273:                 for (ExecutionJobVertex ejv : verticesInCreationOrder) {
1274:                     final Map<Integer, Integer> subtaskToFinishedAttempt =
1275:                             Arrays.stream(ejv.getTaskVertices())
1276:                                     .map(ExecutionVertex::getCurrentExecutionAttempt)
1277:                                     .collect(
1278:                                             Collectors.toMap(
1279:                                                     Execution::getParallelSubtaskIndex,
1280:                                                     Execution::getAttemptNumber));
1281:                     ejv.getJobVertex()
1282:                             .finalizeOnMaster(
1283:                                     new FinalizeOnMasterContext() {
1284:                                         @Override
1285:                                         public ClassLoader getClassLoader() {
1286:                                             return getUserClassLoader();
1287:                                         }
1288: 
1289:                                         @Override
1290:                                         public int getExecutionParallelism() {
1291:                                             return ejv.getParallelism();
1292:                                         }
1293: 
1294:                                         @Override
1295:                                         public int getFinishedAttempt(int subtaskIndex) {
1296:                                             final Integer attemptNumber =
1297:                                                     subtaskToFinishedAttempt.get(subtaskIndex);
1298:                                             if (attemptNumber == null) {
1299:                                                 throw new IllegalArgumentException(
1300:                                                         "Invalid subtaskIndex "
1301:                                                                 + subtaskIndex
1302:                                                                 + " provided");
1303:                                             }
1304:                                             return attemptNumber;
1305:                                         }
1306:                                     });
1307:                 }
1308:             } catch (Throwable t) {
1309:                 ExceptionUtils.rethrowIfFatalError(t);
1310:                 ClusterEntryPointExceptionUtils.tryEnrichClusterEntryPointError(t);
1311:                 failGlobal(new Exception("Failed to finalize execution on master", t));
1312:                 return;
1313:             }
1314: 
1315:             // if we do not make this state transition, then a concurrent
1316:             // cancellation or failure happened
1317:             if (transitionState(JobStatus.RUNNING, JobStatus.FINISHED)) {
1318:                 onTerminalState(JobStatus.FINISHED);
1319:             }
1320:         }
1321:     }
