1368:     @Override
1369:     public void failJob(Throwable cause, long timestamp) {
1370:         if (state == JobStatus.FAILING || state.isTerminalState()) {
1371:             return;
1372:         }
1373: 
1374:         transitionState(JobStatus.FAILING, cause);
1375:         initFailureCause(cause, timestamp);
1376: 
1377:         FutureUtils.assertNoException(
1378:                 applyToVertexAsync(ExecutionJobVertex::cancelWithFuture)
1379:                         .whenComplete(
1380:                                 (aVoid, throwable) -> {
1381:                                     if (transitionState(
1382:                                             JobStatus.FAILING, JobStatus.FAILED, cause)) {
1383:                                         onTerminalState(JobStatus.FAILED);
1384:                                     } else if (state == JobStatus.CANCELLING) {
1385:                                         transitionState(JobStatus.CANCELLING, JobStatus.CANCELED);
1386:                                         onTerminalState(JobStatus.CANCELED);
1387:                                     } else if (!state.isTerminalState()) {
1388:                                         throw new IllegalStateException(
1389:                                                 "Cannot complete job failing from an unexpected state: "
1390:                                                         + state);
