1395:     private void onTerminalState(JobStatus status) {
1396:         LOG.debug("ExecutionGraph {} reached terminal state {}.", getJobID(), status);
1397: 
1398:         try {
1399:             CheckpointCoordinator coord = this.checkpointCoordinator;
1400:             this.checkpointCoordinator = null;
1401:             if (coord != null) {
1402:                 coord.shutdown();
1403:             }
1404:             if (checkpointCoordinatorTimer != null) {
1405:                 checkpointCoordinatorTimer.shutdownNow();
1406:                 checkpointCoordinatorTimer = null;
1407:             }
1408:         } catch (Exception e) {
1409:             LOG.error("Error while cleaning up after execution", e);
1410:         } finally {
1411:             terminationFuture.complete(status);
1412:         }
1413:     }
