371:     private List<SETUP> setupReporters(
372:             Map<String, REPORTER_FACTORY> reporterFactories,
373:             List<Tuple2<String, Configuration>> reporterConfigurations) {
374:         List<SETUP> reporterSetups = new ArrayList<>(reporterConfigurations.size());
375:         for (Tuple2<String, Configuration> reporterConfiguration : reporterConfigurations) {
376:             String reporterName = reporterConfiguration.f0;
377:             Configuration reporterConfig = reporterConfiguration.f1;
378: 
379:             try {
380:                 Optional<REPORTER> metricReporterOptional =
381:                         loadReporter(reporterName, reporterConfig, reporterFactories);
382: 
383:                 final MetricFilter metricFilter =
384:                         DefaultMetricFilter.fromConfiguration(reporterConfig);
385: 
386:                 // massage user variables keys into scope format for parity to variable
387:                 // exclusion
388:                 Map<String, String> additionalVariables =
389:                         reporterConfig.get(reporterSetupInfo.reporterAdditionalVariables).entrySet()
390:                                 .stream()
391:                                 .collect(
392:                                         Collectors.toMap(
393:                                                 e -> ScopeFormat.asVariable(e.getKey()),
394:                                                 Map.Entry::getValue));
395: 
396:                 metricReporterOptional.ifPresent(
397:                         reporter -> {
398:                             MetricConfig metricConfig = new MetricConfig();
399:                             reporterConfig.addAllToProperties(metricConfig);
400:                             reporterSetups.add(
401:                                     createReporterSetup(
402:                                             reporterName,
403:                                             metricConfig,
404:                                             reporter,
405:                                             metricFilter,
406:                                             additionalVariables));
407:                         });
408:             } catch (Throwable t) {
409:                 LOG.error(
410:                         "Could not instantiate {} {}. Reporting might not be exposed.",
411:                         reporterSetupInfo.reporterTypeClass.getSimpleName(),
412:                         reporterName,
413:                         t);
414:             }
415:         }
416:         return reporterSetups;
417:     }
418: 
419:     private Optional<REPORTER> loadReporter(
420:             final String reporterName,
421:             final Configuration reporterConfig,
422:             final Map<String, REPORTER_FACTORY> reporterFactories) {
423: 
424:         final String factoryClassName = reporterConfig.get(reporterSetupInfo.factoryClassConfig);
425: 
426:         if (factoryClassName != null) {
427:             return loadViaFactory(
428:                     factoryClassName, reporterName, reporterConfig, reporterFactories);
429:         }
430: 
431:         LOG.warn(
432:                 "No reporter factory set for reporter {}. Events might not be exposed/reported.",
433:                 reporterName);
434:         return Optional.empty();
435:     }
436: 
437:     private Optional<REPORTER> loadViaFactory(
438:             final String factoryClassName,
439:             final String reporterName,
440:             final Configuration reporterConfig,
441:             final Map<String, REPORTER_FACTORY> reporterFactories) {
442: 
443:         REPORTER_FACTORY factory = reporterFactories.get(factoryClassName);
444: 
445:         if (factory == null) {
446:             LOG.warn(
447:                     "The reporter factory ({}) could not be found for reporter {}. Available factories: {}.",
448:                     factoryClassName,
449:                     reporterName,
450:                     reporterFactories.keySet());
451:             return Optional.empty();
452:         } else {
453:             return loadViaFactory(reporterConfig, factory);
454:         }
455:     }
456: 
457:     private Optional<REPORTER> loadViaFactory(
458:             final Configuration reporterConfig, final REPORTER_FACTORY factory) {
459: 
460:         final MetricConfig metricConfig = new MetricConfig();
461:         reporterConfig.addAllToProperties(metricConfig);
462: 
463:         return Optional.of(reporterSetupInfo.reporterFactoryAdapter.invoke(factory, metricConfig));
464:     }
