310:     private Map<String, REPORTER_FACTORY> loadAvailableReporterFactories(
311:             @Nullable PluginManager pluginManager) {
312:         final Map<String, REPORTER_FACTORY> reporterFactories =
313:                 CollectionUtil.newHashMapWithExpectedSize(2);
314:         final Iterator<REPORTER_FACTORY> factoryIterator = getAllReporterFactories(pluginManager);
315:         // do not use streams or for-each loops here because they do not allow catching
316:         // individual
317:         // ServiceConfigurationErrors
318:         // such an error might be caused if the META-INF/services contains an entry to a
319:         // non-existing factory class
320:         while (factoryIterator.hasNext()) {
321:             try {
322:                 REPORTER_FACTORY factory = factoryIterator.next();
323:                 String factoryClassName = factory.getClass().getName();
324:                 REPORTER_FACTORY existingFactory = reporterFactories.get(factoryClassName);
325:                 if (existingFactory == null) {
326:                     reporterFactories.put(factoryClassName, factory);
327:                     LOG.debug(
328:                             "Found {} {} at {} ",
329:                             reporterSetupInfo.factoryTypeClass.getSimpleName(),
330:                             factoryClassName,
331:                             new File(
332:                                             factory.getClass()
333:                                                     .getProtectionDomain()
334:                                                     .getCodeSource()
335:                                                     .getLocation()
336:                                                     .toURI())
337:                                     .getCanonicalPath());
338:                 } else {
339:                     LOG.warn(
340:                             "Multiple implementations of the same {} were found in 'lib' and/or 'plugins' directories for {}. It is recommended to remove redundant reporter JARs to resolve used versions' ambiguity.",
341:                             reporterSetupInfo.factoryTypeClass.getSimpleName(),
342:                             factoryClassName);
343:                 }
344:             } catch (Exception | ServiceConfigurationError e) {
345:                 LOG.warn(
346:                         "Error while loading {}.",
347:                         reporterSetupInfo.factoryTypeClass.getSimpleName(),
348:                         e);
349:             }
350:         }
351: 
352:         return Collections.unmodifiableMap(reporterFactories);
353:     }
