466:     private List<Tuple2<String, Configuration>> loadReporterConfigurations(
467:             Configuration configuration, Set<String> namedReporters) {
468:         final List<Tuple2<String, Configuration>> reporterConfigurations =
469:                 new ArrayList<>(namedReporters.size());
470: 
471:         for (String namedReporter : namedReporters) {
472:             DelegatingConfiguration delegatingConfiguration =
473:                     new DelegatingConfiguration(
474:                             configuration, reporterSetupInfo.reporterPrefix + namedReporter + '.');
475: 
476:             reporterConfigurations.add(Tuple2.of(namedReporter, delegatingConfiguration));
477:         }
478:         return reporterConfigurations;
479:     }
