181:         private List<ResolvedExpression> executeFlatten(List<ResolvedExpression> args) {
182:             if (args.size() != 1) {
183:                 throw new ValidationException("Invalid number of arguments for flattening.");
184:             }
185:             final ResolvedExpression composite = args.get(0);
186:             final LogicalType compositeType = composite.getOutputDataType().getLogicalType();
187:             if (hasLegacyTypes(compositeType)) {
188:                 return flattenLegacyCompositeType(composite);
189:             }
190:             return flattenCompositeType(composite);
191:         }
