193:         private List<ResolvedExpression> flattenCompositeType(ResolvedExpression composite) {
194:             final DataType dataType = composite.getOutputDataType();
195:             final LogicalType type = dataType.getLogicalType();
196:             if (!isCompositeType(type)) {
197:                 return singletonList(composite);
198:             }
199:             final List<DataType> fieldDataTypes = DataTypeUtils.flattenToDataTypes(dataType);
200:             final List<String> fieldNames = DataTypeUtils.flattenToNames(dataType);
201:             return IntStream.range(0, fieldDataTypes.size())
202:                     .mapToObj(
203:                             idx -> {
204:                                 final DataType fieldDataType = fieldDataTypes.get(idx);
205:                                 final DataType nullableFieldDataType;
206:                                 if (type.isNullable()) {
207:                                     nullableFieldDataType = fieldDataType.nullable();
208:                                 } else {
209:                                     nullableFieldDataType = fieldDataType;
210:                                 }
211:                                 return resolutionContext
212:                                         .postResolutionFactory()
213:                                         .get(
214:                                                 composite,
215:                                                 valueLiteral(fieldNames.get(idx)),
216:                                                 nullableFieldDataType);
217:                             })
218:                     .collect(Collectors.toList());
219:         }
