365:         private ResolvedExpression runTypeInference(
366:                 String functionName,
367:                 UnresolvedCallExpression unresolvedCall,
368:                 TypeInference inference,
369:                 List<ResolvedExpression> resolvedArgs,
370:                 @Nullable SurroundingInfo surroundingInfo) {
371:             if (inference == null) {
372:                 throw new TableException(
373:                         "Could not get a type inference for function: " + functionName);
374:             }
375: 
376:             final Result inferenceResult =
377:                     TypeInferenceUtil.runTypeInference(
378:                             inference,
379:                             new TableApiCallContext(
380:                                     resolutionContext.typeFactory(),
381:                                     functionName,
382:                                     unresolvedCall.getFunctionDefinition(),
383:                                     resolvedArgs,
384:                                     resolutionContext.isGroupedAggregation()),
385:                             surroundingInfo);
386: 
387:             final List<ResolvedExpression> adaptedArguments =
388:                     castArguments(inferenceResult, resolvedArgs);
389: 
390:             return unresolvedCall.resolve(adaptedArguments, inferenceResult.getOutputDataType());
391:         }
392: 
393:         /** Casts the arguments according to the properties of the {@link Result}. */
394:         private List<ResolvedExpression> castArguments(
395:                 Result inferenceResult, List<ResolvedExpression> resolvedArgs) {
396: 
397:             return IntStream.range(0, resolvedArgs.size())
398:                     .mapToObj(
399:                             pos -> {
400:                                 final ResolvedExpression argument = resolvedArgs.get(pos);
401:                                 final DataType argumentType = argument.getOutputDataType();
402:                                 final DataType expectedType =
403:                                         inferenceResult.getExpectedArgumentTypes().get(pos);
404: 
405:                                 if (!supportsAvoidingCast(
406:                                         argumentType.getLogicalType(),
407:                                         expectedType.getLogicalType())) {
408:                                     return resolutionContext
409:                                             .postResolutionFactory()
410:                                             .cast(argument, expectedType);
411:                                 }
412:                                 return argument;
413:                             })
414:                     .collect(Collectors.toList());
415:         }
