417:         /** Validates and cleans an inline, unregistered {@link UserDefinedFunction}. */
418:         private FunctionDefinition prepareInlineUserDefinedFunction(FunctionDefinition definition) {
419:             if (definition instanceof ScalarFunctionDefinition) {
420:                 final ScalarFunctionDefinition sf = (ScalarFunctionDefinition) definition;
421:                 UserDefinedFunctionHelper.prepareInstance(
422:                         resolutionContext.configuration(), sf.getScalarFunction());
423:                 return new ScalarFunctionDefinition(sf.getName(), sf.getScalarFunction());
424:             } else if (definition instanceof TableFunctionDefinition) {
425:                 final TableFunctionDefinition tf = (TableFunctionDefinition) definition;
426:                 UserDefinedFunctionHelper.prepareInstance(
427:                         resolutionContext.configuration(), tf.getTableFunction());
428:                 return new TableFunctionDefinition(
429:                         tf.getName(), tf.getTableFunction(), tf.getResultType());
430:             } else if (definition instanceof AggregateFunctionDefinition) {
431:                 final AggregateFunctionDefinition af = (AggregateFunctionDefinition) definition;
432:                 UserDefinedFunctionHelper.prepareInstance(
433:                         resolutionContext.configuration(), af.getAggregateFunction());
434:                 return new AggregateFunctionDefinition(
435:                         af.getName(),
436:                         af.getAggregateFunction(),
437:                         af.getResultTypeInfo(),
438:                         af.getAccumulatorTypeInfo());
439:             } else if (definition instanceof TableAggregateFunctionDefinition) {
440:                 final TableAggregateFunctionDefinition taf =
441:                         (TableAggregateFunctionDefinition) definition;
442:                 UserDefinedFunctionHelper.prepareInstance(
443:                         resolutionContext.configuration(), taf.getTableAggregateFunction());
444:                 return new TableAggregateFunctionDefinition(
445:                         taf.getName(),
446:                         taf.getTableAggregateFunction(),
447:                         taf.getResultTypeInfo(),
448:                         taf.getAccumulatorTypeInfo());
449:             } else if (definition instanceof UserDefinedFunction) {
450:                 UserDefinedFunctionHelper.prepareInstance(
451:                         resolutionContext.configuration(), (UserDefinedFunction) definition);
452:             }
453:             return definition;
454:         }
455:     }
