459:     private static class TableApiCallContext implements CallContext {
460: 
461:         private final DataTypeFactory typeFactory;
462: 
463:         private final String functionName;
464: 
465:         private final FunctionDefinition definition;
466: 
467:         private final List<ResolvedExpression> resolvedArgs;
468: 
469:         private final boolean isGroupedAggregation;
470: 
471:         public TableApiCallContext(
472:                 DataTypeFactory typeFactory,
473:                 String functionName,
474:                 FunctionDefinition definition,
475:                 List<ResolvedExpression> resolvedArgs,
476:                 boolean isGroupedAggregation) {
477:             this.typeFactory = typeFactory;
478:             this.functionName = functionName;
479:             this.definition = definition;
480:             this.resolvedArgs = resolvedArgs;
481:             this.isGroupedAggregation = isGroupedAggregation;
482:         }
483: 
484:         @Override
485:         public DataTypeFactory getDataTypeFactory() {
486:             return typeFactory;
487:         }
488: 
489:         @Override
490:         public FunctionDefinition getFunctionDefinition() {
491:             return definition;
492:         }
493: 
494:         @Override
495:         public boolean isArgumentLiteral(int pos) {
496:             final ResolvedExpression arg = getArgument(pos);
497:             return arg instanceof ValueLiteralExpression || arg instanceof TypeLiteralExpression;
498:         }
499: 
500:         @Override
501:         public boolean isArgumentNull(int pos) {
502:             final ResolvedExpression arg = getArgument(pos);
503:             if (isFunction(arg, BuiltInFunctionDefinitions.DEFAULT)) {
504:                 return true;
505:             }
506:             if (arg instanceof ValueLiteralExpression) {
507:                 final ValueLiteralExpression literal = (ValueLiteralExpression) arg;
508:                 return literal.isNull();
509:             }
510:             return false;
511:         }
512: 
513:         @Override
514:         @SuppressWarnings("unchecked")
515:         public <T> Optional<T> getArgumentValue(int pos, Class<T> clazz) {
516:             final ResolvedExpression arg = getArgument(pos);
517:             if (arg instanceof TypeLiteralExpression) {
518:                 if (!DataType.class.isAssignableFrom(clazz)) {
519:                     return Optional.empty();
520:                 }
521:                 return Optional.of((T) arg.getOutputDataType());
522:             }
523:             if (arg instanceof ValueLiteralExpression) {
524:                 final ValueLiteralExpression literal = (ValueLiteralExpression) arg;
525:                 return literal.getValueAs(clazz);
526:             }
527:             return Optional.empty();
528:         }
529: 
530:         @Override
531:         public String getName() {
532:             return functionName;
533:         }
534: 
535:         @Override
536:         public List<DataType> getArgumentDataTypes() {
537:             return resolvedArgs.stream()
538:                     .map(ResolvedExpression::getOutputDataType)
539:                     .collect(Collectors.toList());
540:         }
541: 
542:         @Override
543:         public Optional<DataType> getOutputDataType() {
544:             return Optional.empty();
545:         }
546: 
547:         @Override
548:         public boolean isGroupedAggregation() {
549:             return isGroupedAggregation;
550:         }
551: 
552:         private ResolvedExpression getArgument(int pos) {
553:             if (pos >= resolvedArgs.size()) {
554:                 throw new IndexOutOfBoundsException(
555:                         String.format(
556:                                 "Not enough arguments to access literal at position %d for function '%s'.",
557:                                 pos,
558:                                 functionName));
559:             }
560:             return resolvedArgs.get(pos);
561:         }
562:     }
563: }
