656:     /**
657:      * Creates the parallelism store that should be used for determining scheduling requirements,
658:      * which may choose different parallelisms than set in the {@link JobGraph} depending on the
659:      * execution mode.
660:      *
661:      * @param jobGraph The job graph for execution.
662:      * @param executionMode The mode of scheduler execution.
663:      * @return The parallelism store.
664:      */
665:     private static VertexParallelismStore computeVertexParallelismStore(
666:             JobGraph jobGraph, SchedulerExecutionMode executionMode) {
667:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
668:             return computeReactiveModeVertexParallelismStore(
669:                     jobGraph.getVertices(), SchedulerBase::getDefaultMaxParallelism, true);
670:         }
671:         return SchedulerBase.computeVertexParallelismStore(jobGraph);
672:     }
