352:     private class OverwriteObjectsCross
353:             implements CrossFunction<
354:                     Tuple2<IntValue, IntValue>,
355:                     Tuple2<IntValue, IntValue>,
356:                     Tuple2<IntValue, IntValue>> {
357:         private Scrambler scrambler = new Scrambler(true);
358: 
359:         @Override
360:         public Tuple2<IntValue, IntValue> cross(
361:                 Tuple2<IntValue, IntValue> a, Tuple2<IntValue, IntValue> b) throws Exception {
362:             return scrambler.scramble(a, b);
363:         }
364:     }
365: 
366:     // --------------------------------------------------------------------------------------------
367: 
368:     private DataSet<Tuple2<IntValue, IntValue>> getDataSet(
369:             ExecutionEnvironment env, int numberOfElements, int keyRange) {
370:         return env.fromCollection(
371:                 new TupleIntValueIntValueIterator(numberOfElements, keyRange),
372:                 TupleTypeInfo.<Tuple2<IntValue, IntValue>>getBasicAndBasicValueTupleTypeInfo(
373:                         IntValue.class, IntValue.class));
374:     }
375: 
376:     private DataSet<Tuple2<IntValue, IntValue>> getDataSet(ExecutionEnvironment env) {
377:         return getDataSet(env, NUMBER_OF_ELEMENTS, KEY_RANGE);
378:     }
