1374:         if (!resultFuture.isDone()) {
1375:             CompletableFuture<S> expected =
1376:                     client.getKvState(jobId, queryName, key, keyTypeInfo, stateDescriptor);
1377:             expected.whenCompleteAsync(
1378:                     (result, throwable) -> {
