490:     /**
491:      * Infinite source which notifies when all of its sub tasks have been started via the count down
492:      * latch.
493:      */
494:     public static class NotifyingInfiniteTupleSource
495:             extends ManualWindowSpeedITCase.InfiniteTupleSource {
496: 
497:         private static final long serialVersionUID = 8120981235081181746L;
498: 
499:         private static CountDownLatch countDownLatch;
500: 
501:         public NotifyingInfiniteTupleSource(int numKeys) {
502:             super(numKeys);
503:         }
504: 
505:         @Override
506:         public void run(SourceContext<Tuple2<String, Integer>> out) throws Exception {
507:             if (countDownLatch != null) {
508:                 countDownLatch.countDown();
509:             }
510: 
511:             super.run(out);
512:         }
513:     }
