68: 
69:     WaitingForResources(
70:             Context context,
71:             Logger log,
72:             Duration initialResourceAllocationTimeout,
73:             Duration stateTransitionManagerFactory,
74:             Clock clock,
75:             @Nullable ExecutionGraph previousExecutionGraph) {
76:         super(context, log);
77:         this.context = Preconditions.checkNotNull(context);
78:         this.stateTransitionManagerFactory =
79:                 Preconditions.checkNotNull(stateTransitionManagerFactory);
80:         this.clock = clock;
81:         Preconditions.checkNotNull(initialResourceAllocationTimeout);
82: 
83:         Preconditions.checkArgument(
84:                 !stateTransitionManagerFactory.isNegative(),
85:                 "Resource stabilization timeout must not be negative");
86: 
87:         // since state transitions are not allowed in state constructors, schedule calls for later.
88:         if (!initialResourceAllocationTimeout.isNegative()) {
89:             resourceTimeoutFuture =
90:                     context.runIfState(
91:                             this, this::resourceTimeout, initialResourceAllocationTimeout);
92:         }
93:         this.previousExecutionGraph = previousExecutionGraph;
94:         context.runIfState(this, this::checkDesiredOrSufficientResourcesAvailable, Duration.ZERO);
95:     }
96: 
97:     @Override
98:     public void onLeave(Class<? extends State> newState) {
99:         if (resourceTimeoutFuture != null) {
100:             resourceTimeoutFuture.cancel(false);
101:         }
102:     }
103: 
104:     @Override
105:     public JobStatus getJobStatus() {
106:         return JobStatus.CREATED;
107:     }
108: 
109:     @Override
110:     public void onNewResourcesAvailable() {
111:         checkDesiredOrSufficientResourcesAvailable();
112:     }
113: 
114:     @Override
115:     public void onNewResourceRequirements() {
116:         checkDesiredOrSufficientResourcesAvailable();
117:     }
118: 
119:     private void checkDesiredOrSufficientResourcesAvailable() {
120:         if (context.hasDesiredResources()) {
121:             createExecutionGraphWithAvailableResources();
122:             return;
123:         }
124: 
125:         if (context.hasSufficientResources()) {
126:             if (resourceStabilizationDeadline == null) {
127:                 resourceStabilizationDeadline =
128:                         Deadline.fromNowWithClock(stateTransitionManagerFactory, clock);
129:             }
130:             if (resourceStabilizationDeadline.isOverdue()) {
131:                 createExecutionGraphWithAvailableResources();
132:             } else {
133:                 // schedule next resource check
134:                 context.runIfState(
135:                         this,
136:                         this::checkDesiredOrSufficientResourcesAvailable,
137:                         resourceStabilizationDeadline.timeLeft());
138:             }
139:         } else {
140:             // clear deadline due to insufficient resources
141:             resourceStabilizationDeadline = null;
142:         }
143:     }
144: 
145:     private void resourceTimeout() {
146:         getLogger()
147:                 .debug(
148:                         "Initial resource allocation timeout triggered: Creating ExecutionGraph with available resources.");
149:         createExecutionGraphWithAvailableResources();
150:     }
151: 
152:     private void createExecutionGraphWithAvailableResources() {
153:         context.goToCreatingExecutionGraph(previousExecutionGraph);
154:     }
