162:          *
163:          * @return {@code true} if we have enough resources; otherwise {@code false}
164:          */
165:         boolean hasDesiredResources();
166: 
167:         /**
168:          * Checks if we currently have sufficient resources for executing the job.
169:          *
170:          * @return {@code true} if we have sufficient resources; otherwise {@code false}
171:          */
172:         boolean hasSufficientResources();
173: 
