46: /** Array {@link ColumnReader}. TODO Currently ARRAY type only support non nested case. */
47: public class ArrayColumnReader extends BaseVectorizedColumnReader {
48: 
49:     // The value read in last time
50:     private Object lastValue;
51: 
52:     // flag to indicate if there is no data in parquet data page
53:     private boolean eof = false;
54: 
55:     // flag to indicate if it's the first time to read parquet data page with this instance
56:     boolean isFirstRow = true;
