68:     @Override
69:     public void readToVector(int readNumber, WritableColumnVector vector) {
70:         HeapArrayVector lcv = (HeapArrayVector) vector;
71:         // before readBatch, initial the size of offsets & lengths as the default value,
72:         // the actual size will be assigned in setChildrenInfo() after reading complete.
73:         lcv.setOffsets(new long[VectorizedColumnBatch.DEFAULT_SIZE]);
74:         lcv.setLengths(new long[VectorizedColumnBatch.DEFAULT_SIZE]);
75: 
76:         LogicalType elementType = ((ArrayType) logicalType).getElementType();
77: 
78:         // read the first row in parquet data page, this will be only happened once for this
79:         // instance
80:         if (isFirstRow) {
81:             if (!fetchNextValue(elementType)) {
82:                 return;
83:             }
84:             isFirstRow = false;
85:         }
86: 
87:         // Because the length of ListColumnVector.child can't be known now,
88:         // the valueList will save all data for ListColumnVector temporary.
89:         List<Object> valueList = new ArrayList<>();
90: 
91:         int index = collectDataFromParquetPage(readNumber, lcv, valueList, elementType);
92:         // Convert valueList to array for the ListColumnVector.child
93:         fillColumnVector(elementType, lcv, valueList, index);
94:     }
