281:      * actual size according to the element number.
282:      */
283:     private void setChildrenInfo(HeapArrayVector lcv, int itemNum, int elementNum) {
284:         lcv.setSize(itemNum);
285:         long[] lcvLength = new long[elementNum];
286:         long[] lcvOffset = new long[elementNum];
287:         System.arraycopy(lcv.getLengths(), 0, lcvLength, 0, elementNum);
288:         System.arraycopy(lcv.getOffsets(), 0, lcvOffset, 0, elementNum);
289:         lcv.setLengths(lcvLength);
290:         lcv.setOffsets(lcvOffset);
291:     }
