334:     private class RowTypeComparatorBuilder implements TypeComparatorBuilder<Row> {
335: 
336:         private final ArrayList<TypeComparator> fieldComparators = new ArrayList<TypeComparator>();
337:         private final ArrayList<Integer> logicalKeyFields = new ArrayList<Integer>();
338:         private final boolean[] comparatorOrders;
