356:         @Override
357:         public TypeComparator<Row> createTypeComparator(ExecutionConfig config) {
358:             checkState(
359:                     fieldComparators.size() > 0,
360:                     "No field comparators were defined for the TupleTypeComparatorBuilder.");
361: 
362:             checkState(
363:                     logicalKeyFields.size() > 0,
364:                     "No key fields were defined for the TupleTypeComparatorBuilder.");
365: 
366:             checkState(
367:                     fieldComparators.size() == logicalKeyFields.size(),
368:                     "The number of field comparators and key fields is not equal.");
369: 
