98:     @Override
99:     public void getFlatFields(
100:             String fieldExpression, int offset, List<FlatFieldDescriptor> result) {
101:         Matcher matcher = PATTERN_NESTED_FIELDS_WILDCARD.matcher(fieldExpression);
102: 
103:         if (!matcher.matches()) {
104:             throw new InvalidFieldReferenceException(
105:                     "Invalid tuple field reference \"" + fieldExpression + "\".");
106:         }
107: 
108:         String field = matcher.group(0);
109: 
110:         if ((field.equals(ExpressionKeys.SELECT_ALL_CHAR))
111:                 || (field.equals(ExpressionKeys.SELECT_ALL_CHAR_SCALA))) {
112:             // handle select all
113:             int keyPosition = 0;
114:             for (TypeInformation<?> fType : types) {
115:                 if (fType instanceof CompositeType) {
116:                     CompositeType<?> cType = (CompositeType<?>) fType;
117:                     cType.getFlatFields(
118:                             ExpressionKeys.SELECT_ALL_CHAR, offset + keyPosition, result);
119:                     keyPosition += cType.getTotalFields() - 1;
120:                 } else {
121:                     result.add(new FlatFieldDescriptor(offset + keyPosition, fType));
122:                 }
123:                 keyPosition++;
124:             }
125:         } else {
126:             field = matcher.group(1);
127: 
128:             Matcher intFieldMatcher = PATTERN_INT_FIELD.matcher(field);
129:             int fieldIndex;
130:             if (intFieldMatcher.matches()) {
131:                 // field expression is an integer
132:                 fieldIndex = Integer.valueOf(field);
133:             } else {
134:                 fieldIndex = this.getFieldIndex(field);
135:             }
136:             // fetch the field type will throw exception if the index is illegal
137:             TypeInformation<?> fieldType = this.getTypeAt(fieldIndex);
138:             // compute the offset,
139:             for (int i = 0; i < fieldIndex; i++) {
140:                 offset += this.getTypeAt(i).getTotalFields();
141:             }
142: 
143:             String tail = matcher.group(3);
144: 
145:             if (tail == null) {
146:                 // expression hasn't nested field
147:                 if (fieldType instanceof CompositeType) {
148:                     ((CompositeType) fieldType).getFlatFields("*", offset, result);
149:                 } else {
150:                     result.add(new FlatFieldDescriptor(offset, fieldType));
151:                 }
152:             } else {
153:                 // expression has nested field
154:                 if (fieldType instanceof CompositeType) {
155:                     ((CompositeType) fieldType).getFlatFields(tail, offset, result);
156:                 } else {
157:                     throw new InvalidFieldReferenceException(
158:                             "Nested field expression \""
159:                                     + tail
160:                                     + "\" not possible on atomic type "
161:                                     + fieldType
162:                                     + ".");
163:                 }
164:             }
165:         }
166:     }
