168:     @Override
169:     public <X> TypeInformation<X> getTypeAt(String fieldExpression) {
170:         Matcher matcher = PATTERN_NESTED_FIELDS.matcher(fieldExpression);
171:         if (!matcher.matches()) {
172:             if (fieldExpression.equals(ExpressionKeys.SELECT_ALL_CHAR)
173:                     || fieldExpression.equals(ExpressionKeys.SELECT_ALL_CHAR_SCALA)) {
174:                 throw new InvalidFieldReferenceException(
175:                         "Wildcard expressions are not allowed here.");
176:             } else {
177:                 throw new InvalidFieldReferenceException(
178:                         "Invalid format of Row field expression \"" + fieldExpression + "\".");
179:             }
180:         }
181: 
182:         String field = matcher.group(1);
183: 
184:         Matcher intFieldMatcher = PATTERN_INT_FIELD.matcher(field);
185:         int fieldIndex;
186:         if (intFieldMatcher.matches()) {
187:             // field expression is an integer
188:             fieldIndex = Integer.valueOf(field);
189:         } else {
190:             fieldIndex = this.getFieldIndex(field);
191:         }
192:         // fetch the field type will throw exception if the index is illegal
193:         TypeInformation<X> fieldType = this.getTypeAt(fieldIndex);
194: 
195:         String tail = matcher.group(3);
196:         if (tail == null) {
197:             // found the type
198:             return fieldType;
199:         } else {
200:             if (fieldType instanceof CompositeType) {
201:                 return ((CompositeType<?>) fieldType).getTypeAt(tail);
202:             } else {
203:                 throw new InvalidFieldReferenceException(
204:                         "Nested field expression \""
205:                                 + tail
206:                                 + "\" not possible on atomic type "
207:                                 + fieldType
208:                                 + ".");
209:             }
210:         }
211:     }
