324:     private boolean hasDuplicateFieldNames(String[] fieldNames) {
325:         HashSet<String> names = new HashSet<>();
326:         for (String field : fieldNames) {
327:             if (!names.add(field)) {
328:                 return true;
329:             }
330:         }
331:         return false;
