334:     private class RowTypeComparatorBuilder implements TypeComparatorBuilder<Row> {
335: 
336:         private final ArrayList<TypeComparator> fieldComparators = new ArrayList<TypeComparator>();
337:         private final ArrayList<Integer> logicalKeyFields = new ArrayList<Integer>();
338:         private final boolean[] comparatorOrders;
339: 
340:         public RowTypeComparatorBuilder(boolean[] comparatorOrders) {
341:             this.comparatorOrders = comparatorOrders;
342:         }
343: 
344:         @Override
345:         public void initializeTypeComparatorBuilder(int size) {
346:             fieldComparators.ensureCapacity(size);
347:             logicalKeyFields.ensureCapacity(size);
348:         }
349: 
350:         @Override
351:         public void addComparatorField(int fieldId, TypeComparator<?> comparator) {
352:             fieldComparators.add(comparator);
353:             logicalKeyFields.add(fieldId);
354:         }
355: 
356:         @Override
357:         public TypeComparator<Row> createTypeComparator(ExecutionConfig config) {
358:             checkState(
359:                     fieldComparators.size() > 0,
360:                     "No field comparators were defined for the TupleTypeComparatorBuilder.");
361: 
362:             checkState(
363:                     logicalKeyFields.size() > 0,
364:                     "No key fields were defined for the TupleTypeComparatorBuilder.");
365: 
366:             checkState(
367:                     fieldComparators.size() == logicalKeyFields.size(),
368:                     "The number of field comparators and key fields is not equal.");
369: 
370:             final int len = Collections.max(logicalKeyFields);
371: 
372:             checkState(len >= 0, "The maximum key field must be greater or equal than 0.");
373: 
374:             TypeSerializer<?>[] fieldSerializers = new TypeSerializer<?>[len + 1];
375: 
376:             for (int i = 0; i <= len; i++) {
377:                 fieldSerializers[i] = types[i].createSerializer(config);
378:             }
379: 
380:             int[] keyPositions = new int[logicalKeyFields.size()];
381:             for (int i = 0; i < keyPositions.length; i++) {
382:                 keyPositions[i] = logicalKeyFields.get(i);
383:             }
384: 
385:             TypeComparator[] comparators = new TypeComparator[fieldComparators.size()];
386:             for (int i = 0; i < fieldComparators.size(); i++) {
387:                 comparators[i] = fieldComparators.get(i);
388:             }
389: 
390:             //noinspection unchecked
391:             return new RowComparator(
392:                     getArity(),
393:                     keyPositions,
394:                     comparators,
395:                     (TypeSerializer<Object>[]) fieldSerializers,
396:                     comparatorOrders);
397:         }
398:     }
